begin;

create table if not exists tongs.reference_visual_sequence_sequences(
 workspace_id uuid not null,
 workpiece_id uuid not null,
 opportunity_id uuid not null,
 sequence_id uuid not null,
 current_sequence_revision_id uuid not null,
 current_sequence_revision bigint not null,
 updated_at timestamptz not null default now(),
 primary key(workspace_id,workpiece_id,opportunity_id),
 foreign key(current_sequence_revision_id,workspace_id,workpiece_id,sequence_id,current_sequence_revision)
  references tongs.reference_visual_sequence_revisions(id,workspace_id,workpiece_id,sequence_id,revision)
);
alter table tongs.reference_visual_sequence_sequences enable row level security;
create policy reference_visual_sequence_sequences_viewer on tongs.reference_visual_sequence_sequences
 for select to authenticated using(tongs.has_workspace_role(workspace_id,'viewer'));
revoke all on tongs.reference_visual_sequence_sequences from public,anon,authenticated;
grant select on tongs.reference_visual_sequence_sequences to authenticated;
grant all on tongs.reference_visual_sequence_sequences to service_role;

create or replace function tongs.record_reference_visual_source_acquired(p_operation_id text,p_operation_fingerprint text,p_source_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_acquisition_operations%rowtype;begin select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor')then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state<>'pending' then if op.source_evidence_json is distinct from p_source_evidence then return jsonb_build_object('disposition','source_evidence_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;update tongs.reference_visual_acquisition_operations set state='source_acquired',source_evidence_json=p_source_evidence,failed_stage=null,failure_code=null,failure_message=null,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','source_acquired','operation',to_jsonb(op));end$$;

create or replace function tongs.commit_reference_visual_acquisition(p_operation_id text,p_operation_fingerprint text,p_path text,p_mime_type text,p_byte_size bigint,p_content_hash text,p_storage_bucket text,p_storage_key text,p_width integer,p_height integer,p_provenance jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_acquisition_operations%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;a tongs.assets%rowtype;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;h text;ih text;receipt jsonb;begin if auth.role()<>'service_role' then raise exception 'Reference Visual acquisition commit requires service authority' using errcode='42501';end if;select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return op.receipt_json;end if;if op.state<>'source_acquired' then return jsonb_build_object('disposition','source_acquisition_required');end if;if p_mime_type not like'image/%'or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$'or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_image_evidence');end if;select * into o from tongs.reference_visual_opportunity_revisions where id=op.opportunity_revision_id;insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,case when op.acquisition_type='upload'then'creator-upload'else'external-fetch'end,p_operation_id,op.created_by,'reference_visual_image','ready',jsonb_build_object('inspection_authority','tongs-service.v1'),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(op.workspace_id,op.workpiece_id,o.opportunity_id,op.created_by)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_hash',a.content_hash,'opportunity_revision_id',o.id,'rights_revision_id',op.rights_declaration_revision_id,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'revision',1,'content_hash',h,'operation',p_operation_id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,candidate_kind,asset_id,rights_declaration_revision_id,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,op.workspace_id,op.workpiece_id,o.opportunity_id,1,o.id,o.revision,'archival_still',a.id,op.rights_declaration_revision_id,'{}',p_provenance,h,ih,op.created_by)returning * into r;receipt:=jsonb_build_object('disposition','committed','operation_id',p_operation_id,'asset',to_jsonb(a),'candidate_revision',to_jsonb(r),'rights_declaration_revision_id',op.rights_declaration_revision_id);update tongs.reference_visual_acquisition_operations set state='candidate_committed',verified_asset_id=a.id,result_candidate_revision_id=r.id,failed_stage=null,failure_code=null,failure_message=null,receipt_json=receipt,updated_at=now()where operation_id=p_operation_id;return receipt;end$$;

create or replace function tongs.commit_reference_visual_sequence(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_revision_id uuid,p_sequence_id uuid,p_expected_revision bigint,p_rights_declaration_revision_id uuid,p_members jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_sequence_sequences%rowtype;prev tongs.reference_visual_sequence_revisions%rowtype;s tongs.reference_visual_sequence_revisions%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;item jsonb;ord integer:=0;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;h text;ih text;result jsonb;begin if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if jsonb_typeof(p_members)<>'array'or jsonb_array_length(p_members)<2 then return jsonb_build_object('disposition','sequence_members_required');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;select * into o from tongs.reference_visual_opportunity_revisions where id=p_opportunity_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and visual_subtype='archival_sequence';if not found then return jsonb_build_object('disposition','current_archival_sequence_required');end if;if not exists(select 1 from tongs.reference_visual_plan_sequences ps join lateral(select ss.id from tongs.reference_visual_source_set_revisions ss where ss.workspace_id=p_workspace_id and ss.workpiece_id=p_workpiece_id and ss.opportunity_id=o.opportunity_id and ss.plan_revision_id=ps.current_plan_revision_id order by ss.revision desc limit 1)current_set on true join tongs.reference_visual_source_set_members sm on sm.source_set_revision_id=current_set.id where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id)then return jsonb_build_object('disposition','current_source_collection_required');end if;if not exists(select 1 from tongs.reference_visual_rights_declaration_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id and current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;select * into seq from tongs.reference_visual_sequence_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id for update;if coalesce(seq.current_sequence_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','sequence_revision_conflict','current_revision',coalesce(seq.current_sequence_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_sequence_revisions where id=seq.current_sequence_revision_id;end if;if exists(select 1 from jsonb_array_elements(p_members)x left join tongs.assets a on a.id=(x->>'asset_id')::uuid and a.workspace_id=p_workspace_id and a.workpiece_id=p_workpiece_id and a.status='ready' and a.mime_type like'image/%' left join tongs.source_revisions sr on sr.id=(x->>'source_revision_id')::uuid and sr.workspace_id=p_workspace_id left join tongs.workpiece_source_link_revisions lr on lr.id=(x->>'workpiece_source_link_revision_id')::uuid and lr.workpiece_id=p_workpiece_id and lr.source_revision_id=sr.id where a.id is null or sr.id is null or lr.id is null)then return jsonb_build_object('disposition','canonical_sequence_member_evidence_required');end if;h:=encode(extensions.digest(convert_to(p_members::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',p_expected_revision+1,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_sequence_revisions(sequence_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,content_hash,immutable_revision_hash,created_by)values(p_sequence_id,p_workspace_id,p_workpiece_id,o.opportunity_id,p_expected_revision+1,prev.id,prev.revision,h,ih,p_actor_id)returning * into s;for item in select value from jsonb_array_elements(p_members)loop insert into tongs.reference_visual_sequence_membership values(s.id,p_workspace_id,p_workpiece_id,ord,(item->>'asset_id')::uuid,(item->>'source_revision_id')::uuid,(item->>'workpiece_source_link_revision_id')::uuid,nullif(item->>'duration_ms','')::bigint,coalesce(item->'transition_hints','{}'));ord:=ord+1;end loop;insert into tongs.reference_visual_sequence_sequences values(p_workspace_id,p_workpiece_id,o.opportunity_id,p_sequence_id,s.id,s.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set sequence_id=excluded.sequence_id,current_sequence_revision_id=excluded.current_sequence_revision_id,current_sequence_revision=excluded.current_sequence_revision,updated_at=now();insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(p_workspace_id,p_workpiece_id,o.opportunity_id,p_actor_id)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('sequence_revision_id',s.id,'rights_revision_id',p_rights_declaration_revision_id)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'revision',1,'content_hash',h)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,candidate_kind,sequence_revision_id,rights_declaration_revision_id,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,p_workspace_id,p_workpiece_id,o.opportunity_id,1,o.id,o.revision,'archival_sequence',s.id,p_rights_declaration_revision_id,'{}',jsonb_build_object('authority','tongs-sequence-v1'),h,ih,p_actor_id)returning * into r;result:=jsonb_build_object('disposition','committed','sequence_revision',to_jsonb(s),'candidate_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'sequence_commit',p_workspace_id,p_workpiece_id,'committed',s.id,result,p_actor_id,now());return result;end$$;

revoke all on function tongs.record_reference_visual_source_acquired(text,text,jsonb),tongs.commit_reference_visual_sequence(uuid,uuid,uuid,uuid,bigint,uuid,jsonb,text,text,uuid) from public,anon,authenticated;
grant execute on function tongs.record_reference_visual_source_acquired(text,text,jsonb),tongs.commit_reference_visual_sequence(uuid,uuid,uuid,uuid,bigint,uuid,jsonb,text,text,uuid) to authenticated,service_role;
revoke all on function tongs.commit_reference_visual_acquisition(text,text,text,text,bigint,text,text,text,integer,integer,jsonb) from public,anon,authenticated;
grant execute on function tongs.commit_reference_visual_acquisition(text,text,text,text,bigint,text,text,text,integer,integer,jsonb) to service_role;

notify pgrst,'reload schema';

commit;
